/lua minetest.register_tool( ":bear:kill_hammer", {     description = "Kill Hammer",     inventory_image = "default_stick.png",     groups = { tool = 1, dig_speed_class = 7, enchantability = 100 },     tool_capabilities = {         full_punch_interval = 0.1,         max_drop_level = 0,         punch_attack_uses = -1,     },     sound = { breaks = "default_tool_breaks" },     on_place = mcl_tools.tool_place_funcs.pick,     on_use = function(itemstack, user, pointed_thing)         mcl_tools.entity = pointed_thing.ref         local playerref = mcl_tools.entity         if pointed_thing.type == "object" then             if mcl_tools.entity:is_player() and mcl_tools.entity:get_player_name() then                 playerref = minetest.get_player_by_name(mcl_tools.entity:get_player_name())             end             if mcl_tools.entity:is_player() or mcl_tools.entity:get_luaentity() then                 mcl_tools.entity:set_hp(0)                 minetest.sound_play("tnt_explode", {})                 minetest.sound_play("lightning_thunder", {})                 minetest.sound_play("default_glass", {})             end         end     end,     _mcl_toollike_wield = true, }) 